import{_ as r,l as o,o as a,c as n,v as l,p as d,x as i,d as p,i as s,S as L}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"多模态编码器流水","description":"","frontmatter":{"title":"多模态编码器流水","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vision-encoder-pipeline.md","filePath":"llm/vision-encoder-pipeline.md","lastUpdated":1789023840000}'),_={name:"llm/vision-encoder-pipeline.md"};function c(h,e,m,f,E,T){const t=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=l('<h1 id="多模态编码器流水" tabindex="-1">多模态编码器流水 <a class="header-anchor" href="#多模态编码器流水" aria-label="Permalink to &quot;多模态编码器流水&quot;">​</a></h1><div class="epigraph"><p>图像先被视觉编码器变成一串 token，再与文本一起做语言模型 prefill；两段的屋顶不同，串行等待会把首 token 延迟写成两者之和。</p><footer>—— Radford et al., CLIP；视觉指令对齐见 Liu et al., LLaVA；服务上把编码器与 LLM 分阶段调度</footer></div><p><a href="/llm/tokenizer-parallel">上一课</a>把文本 id 并行化。多模态请求还要跑 ViT / 音频编码器。CLIP 把图像编进与文本对齐的空间；LLaVA 一类把视觉 token 投进 LLM 的 embedding 维。本课写 <em>流水</em>：编码器是算力密、形状由分辨率决定；LLM prefill 吃视觉 token 长度 \\(n_v\\) 加文本。串行则 TTFT \\(=T_{\\mathrm{enc}}+T_{\\mathrm{prefill}}\\)；重叠与连续批要把编码器当成另一类 prefill 池。不重写连接器结构，见主干视觉课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n_v\\) 随分辨率与 patch 走，可以比文本提示还长，直接打进<a href="/llm/long-context-memory-curve">长上下文曲线</a>的 KV 与二次项。编码器本身不写 LLM 的 KV，但占用 GPU。若与 decode 混在同一张卡，正在吐词的用户被一张图的 ViT 挡住。缺口是阶段拆分：视觉编码、投影、LLM prefill、decode 是否同池，以及编码器批处理（多张图拼 batch）如何与变长 \\(n_v\\) 共存。</p><p>动态分辨率（AnyRes、切块）让 \\(n_v\\) 请求间不同，连续批更难。会计必须用实际 \\(n_v\\)，不能用「一张图 = 256 token」的旧默认。</p><p><span class="marginnote">视觉 token 的 KV 在 LLM 侧与文本 KV 同公式。减 \\(n_v\\)（池化、压缩）是容量优化，与 CLIP 质量权衡，不是本课的核融合细节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>独立编码器流或独立池：图在编码器上跑时，文本分词与系统前缀 KV 可并行准备。编码器输出再投影，插入 LLM prefill。连续批：编码器按图像批，LLM 按 token 批，中间有队列。失败回退：编码失败不应占着 LLM 槽。投机对视觉前缀通常只在文本生成段，视觉段是 prefill，投机收益小。</p><p>与 <a href="/llm/flashattention">FlashAttention</a>：LLM prefill 的 \\(n=n_v+n_{\\text{text}}\\)，二次项主要来自视觉。压缩 \\(n_v\\) 对 TTFT 的导数往往大于再调 LLM 核。</p>',10)),(a(),d(L,null,{default:i(()=>[s(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20ENC%5B%22%E8%A7%86%E8%A7%89%E7%BC%96%E7%A0%81%E5%99%A8%E6%B1%A0%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20TOK%5B%22%E5%88%86%E8%AF%8D%22%5D%0A%20%20ENC%20--%3E%20PRJ%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%20LLM%20%E7%BB%B4%22%5D%0A%20%20TOK%20--%3E%20PRE%5B%22LLM%20prefill%22%5D%0A%20%20PRJ%20--%3E%20PRE%0A%20%20PRE%20--%3E%20DEC%5B%22%E6%96%87%E6%9C%AC%20decode%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两段屋顶：ViT 像训练时的视觉骨干，算力绑定；随后 LLM prefill 也算力绑定，但形状是序列。拆池是为了别让 decode 带宽型工作与 ViT 抢 SM。成本模型应分列「每图编码」与「每视觉 token 的 LLM prefill」，否则定价只按输出字会亏在高分辨率上。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在 CPU 上跑大 ViT 还期待与 GPU LLM 流水（除非刻意端侧）。不要把编码器权重与 LLM 权重轮流换入同一张显存不够的卡而不算换入延迟。下一课：没有自回归的嵌入 / 重排服务，批处理画像又不同。</p><p>出处：Radford et al., CLIP；Liu et al., LLaVA。服务调度是工程延伸，不发明论文号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视觉编码与 LLM prefill 是两段；串行 TTFT 是相加。</li><li>\\(n_v\\) 进入 KV 与二次注意力；分辨率是容量旋钮。</li><li>编码器应与 decode 分池或至少分流。</li><li>文本分词可与编码重叠。</li><li>定价要为每图 / 每视觉 token 分列。</li><li>下一课：嵌入与重排模型服务。</li><li>出处：Radford et al., CLIP；Liu et al., LLaVA。</li></ul>',7))])}const P=r(_,[["render",c]]);export{u as __pageData,P as default};
